def check_sequence(x1, x2, x3, limit=100):
    seq = [x1, x2, x3]
    for i in range(3, limit):
        # x_{i-2} + x_{i-1} = x_i * x_{i+1} - 840? No.
        # The equation is g(n) + g(n+1) = g(n+2)g(n+3) - 840
        # Let's re-index: g(n) + g(n+1) + 840 = g(n+2)g(n+3)
        # For n=1: g(1) + g(2) + 840 = g(3)g(4)
        # For n=2: g(2) + g(3) + 840 = g(4)g(5)
        # So g(n+3) = (g(n) + g(n+1) + 840) / g(n+2)
        # This is not quite right. Let's re-derive.
        # n=1: g(1) + g(2) + 840 = g(3)g(4) => g(4) = (g(1) + g(2) + 840) / g(3)
        # n=2: g(2) + g(3) + 840 = g(4)g(5) => g(5) = (g(2) + g(3) + 840) / g(4)
        # So the recurrence is g(n+3) = (g(n) + g(n+1) + 840) / g(n+2) is NOT correct.
        # Let's look at the indices again.
        # n=1: g(1) + g(2) = g(3)g(4) - 840  => g(3)g(4) = g(1) + g(2) + 840
        # n=2: g(2) + g(3) = g(4)g(5) - 840  => g(4)g(5) = g(2) + g(3) + 840
        # n=3: g(3) + g(4) = g(5)g(6) - 840  => g(5)g(6) = g(3) + g(4) + 840
        # The general step is: g(n+2)g(n+3) = g(n) + g(n+1) + 840
        # So g(n+3) = (g(n) + g(n+1) + 840) / g(n+2)
        # Yes, this is what I had.

        numerator = seq[i-3] + seq[i-2] + 840
        denominator = seq[i-1]
        if numerator % denominator != 0:
            return None
        val = numerator // denominator
        if val <= 1:
            return None
        seq.append(val)
    return seq

