def get_sum(seq, n):
    if len(seq) >= n:
        return sum(seq[:n])
    else:
        # If the sequence is periodic, we can extend it
        # But first, check if it's periodic
        period = -1
        for p in range(1, len(seq)//2 + 1):
            if seq[-p:] == seq[-2*p:-p]:
                period = p
                break
        if period != -1:
            # It's periodic. Let's say the periodic part starts at some index.
            # For simplicity, let's just extend it.
            extended_seq = list(seq)
            while len(extended_seq) < n:
                extended_seq.append(extended_seq[len(extended_seq)-period])
            return sum(extended_seq[:n])
        else:
            return None

